from lib import *
S = SS('v73')
steps = [
    step("RED 与 USE。一个 8 个工作线程、队列长度 50 的服务(每个请求基准 20 ms),依次注入四种情形,每个阶段末尾用 10 s 窗口计算。基准:到达 200/s,完成 200/s,错误率 0.0%,平均耗时 26 ms,p99 50 ms,线程利用率 60%,队列最大 0。错误率升高(注入 20% 的请求出错):错误率 17.7%,耗时不变(26 ms),利用率 62%,队列 1。下游变慢(每个请求 60 ms):耗时升到平均 67 ms、p99 100 ms,利用率 81%,队列 0,错误率 0.0%。过载(到达 600/s,超过处理能力):完成只有 307/s,被拒绝 293/s,错误率 48.8%,平均耗时 186 ms、p99 249 ms,利用率 100%,队列满(50)。四种问题在不同指标上露出来,只看一个指标会漏掉另一种问题。", t=tl(S(1)), mark=lidx(S(1), '错误率升高', '过载'), done=lidx(S(1), '基准', '下游变慢'), b=bars([['错误率升高:错误率 %', 17.7, '17.7%'], ['下游变慢:平均耗时 ms', 67, '67 ms'], ['过载:线程利用率 %', 100, '100%'], ['过载:队列长度', 50, '50(满)']], 100, mark=[0, 1], done=[2, 3]), kv=KV([['错误率升高', '只有错误率变(17.7%),耗时和利用率不变'], ['下游变慢', '平均耗时 26 → 67 ms,利用率 60% → 81%'], ['过载', '利用率 100%,队列满,拒绝 293/s,完成 307/s']], ['过载'])),
    step("“错误”的定义。服务收到的请求里 70% 返回 200、25% 返回 404、5% 返回 500。按 5xx ÷ 全部算,错误率是 5.0%;按非 2xx ÷ 全部算,是 30.1%。404 是客户端请求了不存在的资源,不是服务出错;把所有非 2xx 都算错误,错误率被虚高,告警会误报。", t=tl(S(2)), mark=lidx(S(2), '非 2xx'), done=lidx(S(2), '5xx ÷ 全部'), b=bars([['5xx ÷ 全部 %', 5.0, '5.0%'], ['非 2xx ÷ 全部 %', 30.1, '30.1%']], 30.1, done=[0], mark=[1]), kv=KV([['5xx ÷ 全部', '5.0%'], ['非 2xx ÷ 全部', '30.1%(含 25% 的 404)']], ['非 2xx ÷ 全部'])),
]
